"""Mini Lab: the final fallback, and the only one that runs nothing.

When no environment can be produced, RepoLab can still explain what the software
*would* do -- as a conceptual simulation, generated by Super from the repository's
own manifest. CLAUDE.md is unusually strict about this one, because a simulation
that reads like a real result is worse than no result at all:

    always labelled SIMULATED
    link simulated behaviour to real source code
    unsupported commands must state they require a real environment
    never invent output
    never produce performance measurements
    never present simulated results as experimental evidence

Those rules are enforced **here, in code**, not requested in a prompt:

* every entry must cite a file that exists in the repository, and one that cannot
  be tied to a file is dropped -- so "link to real source code" is a property of
  the data structure rather than a hope;
* an unknown command returns the "needs a real environment" response, because
  that is the only response this module can produce for one;
* :func:`validate` refuses a lab containing anything that looks like a
  measurement, and the artifact is not ready until it passes;
* the evidence bundle is built with ``simulated=True``, and
  :class:`~repolab.evidence.models.EvidenceBundle` already makes carrying a
  measurement alongside that combination unrepresentable.
"""

from __future__ import annotations

import re

from pydantic import BaseModel, Field

from repolab.evidence.models import CodeReference, EvidenceBundle
from repolab.llm import LLMError, ModelRouter, Purpose
from repolab.manifest.models import RepoManifest

#: Shown wherever Mini Lab output appears. Not a style choice -- CLAUDE.md
#: requires simulated output be labelled and visually distinct.
SIMULATED_LABEL = "SIMULATED"

#: The answer to anything the lab does not cover. Deliberately the only thing
#: this module will say about an unknown command: inventing plausible output is
#: the specific failure the Mini Lab rules exist to prevent.
NEEDS_REAL_ENVIRONMENT = (
    "This requires a real environment. The Mini Lab is a conceptual simulation "
    "and cannot run this command."
)

#: Entries whose response contains a figure like these are refused.
#:
#: A Mini Lab must never produce a performance measurement, and the easiest way
#: for one to slip in is a model writing "takes about 40ms" into an explanation.
_MEASUREMENT_PATTERN = re.compile(
    r"\b\d[\d,.]*\s*(ms|milliseconds?|s|seconds?|m|minutes?|%|x faster|x slower|"
    r"bytes?|[kmg]i?b|ops?/s|rows?/s|qps|requests?/s)\b",
    re.IGNORECASE,
)

MAX_ENTRIES = 12


def measurement_language(text: str) -> str | None:
    """The measurement-like figure in *text*, if it contains one.

    Public because the Mini Lab *lesson* has to apply the identical rule, and two
    copies of this regular expression would drift apart exactly once and then be
    wrong for a long time.
    """
    found = _MEASUREMENT_PATTERN.search(text)
    return found.group(0) if found is not None else None


class MiniLabEntry(BaseModel):
    """One thing a learner can ask about, and what it conceptually does."""

    command: str
    """What the learner would type, e.g. ``DESCRIBE KEYSPACES;``."""

    concept: str
    """The idea this command illustrates."""

    explanation: str
    """What it would do, conceptually. Never example output."""

    code_references: list[CodeReference] = Field(default_factory=list)
    """Where this behaviour lives in the real repository. Required."""

    @property
    def is_grounded(self) -> bool:
        return bool(self.code_references)


class MiniLabResponse(BaseModel):
    """What the Mini Lab says when asked to run something."""

    command: str
    supported: bool
    simulated: bool = True
    """Always true. There is no unsimulated path through this module."""

    explanation: str
    concept: str = ""
    code_references: list[CodeReference] = Field(default_factory=list)

    @property
    def label(self) -> str:
        return SIMULATED_LABEL


class MiniLab(BaseModel):
    """A conceptual simulation of a repository nobody could build."""

    repo_url: str
    commit_sha: str = ""
    summary: str = ""
    entries: list[MiniLabEntry] = Field(default_factory=list)
    generated_by: str = "deterministic"

    @property
    def grounded_entries(self) -> list[MiniLabEntry]:
        """Entries that cite real code. The only ones this lab will answer with."""
        return [entry for entry in self.entries if entry.is_grounded]

    def respond(self, command: str) -> MiniLabResponse:
        """Answer a command, or say plainly that it needs a real environment."""
        wanted = _normalise(command)
        for entry in self.grounded_entries:
            if _normalise(entry.command) == wanted:
                return MiniLabResponse(
                    command=command,
                    supported=True,
                    explanation=entry.explanation,
                    concept=entry.concept,
                    code_references=list(entry.code_references),
                )
        return MiniLabResponse(command=command, supported=False, explanation=NEEDS_REAL_ENVIRONMENT)

    def evidence(self) -> EvidenceBundle:
        """The lab's evidence: code references only, and marked simulated.

        No measurements, by construction. ``EvidenceBundle`` rejects the
        combination outright, so a Mini Lab that acquired one would fail to
        construct rather than quietly ship.
        """
        references: list[CodeReference] = []
        for entry in self.grounded_entries:
            references.extend(entry.code_references)
        return EvidenceBundle(code_references=references[:20], simulated=True)


class MiniLabInvalid(BaseModel):
    """Why a generated lab was refused."""

    reason: str
    detail: str = ""

    def __str__(self) -> str:
        return f"{self.reason}: {self.detail}" if self.detail else self.reason


def validate(lab: MiniLab) -> MiniLabInvalid | None:
    """Check a lab against the Mini Lab rules. ``None`` means it passed.

    This is the Mini Lab's smoke test. It cannot run a command -- there is no
    environment -- so what it checks instead is that the lab obeys the rules
    that make it safe to show: it says something, every entry it will answer
    with cites real code, and nothing in it reads as a measurement.
    """
    if not lab.grounded_entries:
        return MiniLabInvalid(
            reason="no grounded entries",
            detail="every entry must cite a file in the repository",
        )

    for entry in lab.grounded_entries:
        found = measurement_language(entry.explanation)
        if found is not None:
            return MiniLabInvalid(
                reason="an entry reads as a measurement",
                detail=(
                    f"{entry.command!r} says {found!r}; a Mini Lab must never "
                    "produce a performance measurement"
                ),
            )
    return None


# ---------------------------------------------------------------------------
# Generation
# ---------------------------------------------------------------------------

SYSTEM_PROMPT = (
    "You write conceptual simulations of software you cannot run.\n"
    "\n"
    "For each command a learner might try, say what it would conceptually do and "
    "which concept it illustrates. You are describing behaviour, not producing "
    "output.\n"
    "\n"
    "Rules:\n"
    "- Never write example output. Describe what the command does, not what it "
    "would print.\n"
    "- Never state a duration, size, rate or any other measurement. You have run "
    "nothing and measured nothing.\n"
    "- Only use commands the repository evidence actually supports.\n"
    "- Reference a real file from the list given to you for every entry."
)

PROMPT_TEMPLATE = """\
Repository: {repo_url}
Primary interaction surface: {surface}
Frameworks: {frameworks}

Entry points:
{entrypoints}

Concepts detected in this repository:
{concepts}

Files available to reference (use these paths exactly):
{files}

Write up to {limit} entries a learner could explore, each citing one of those files."""


class _GeneratedEntry(BaseModel):
    """What the model is asked for, per entry."""

    command: str
    concept: str
    explanation: str
    file_path: str


class _GeneratedLab(BaseModel):
    summary: str
    entries: list[_GeneratedEntry]


async def generate(
    manifest: RepoManifest,
    *,
    router: ModelRouter | None = None,
    limit: int = MAX_ENTRIES,
) -> MiniLab:
    """Produce a Mini Lab for *manifest*.

    Super writes it when a router is available; otherwise the deterministic
    fallback builds one from the manifest's own concepts. Either way, entries
    are filtered against the repository's real files afterwards -- a model
    naming a file that does not exist has its entry dropped rather than
    corrected.
    """
    known = _known_files(manifest)

    if router is None or not known:
        return _deterministic(manifest, known)

    try:
        completion = await router.super(
            purpose=Purpose.MINI_LAB_GENERATION,
            schema=_GeneratedLab,
            system=SYSTEM_PROMPT,
            prompt=PROMPT_TEMPLATE.format(
                repo_url=manifest.repo_url,
                surface=(
                    manifest.primary_surface.type.value if manifest.primary_surface else "unknown"
                ),
                frameworks=", ".join(manifest.frameworks) or "none detected",
                entrypoints="\n".join(f"- {e.name}: {e.command}" for e in manifest.entrypoints[:8])
                or "- (none found)",
                concepts="\n".join(f"- {c.name}: {c.summary}" for c in manifest.concepts[:8])
                or "- (none found)",
                files="\n".join(f"- {path}" for path in sorted(known)[:30]),
                limit=limit,
            ),
            max_tokens=2048,
        )
    except LLMError:
        return _deterministic(manifest, known)

    entries: list[MiniLabEntry] = []
    for generated in completion.value.entries[:limit]:
        # A reference to a file that does not exist is not evidence, so the entry
        # is dropped rather than repaired.
        if generated.file_path not in known:
            continue
        entries.append(
            MiniLabEntry(
                command=generated.command,
                concept=generated.concept,
                explanation=generated.explanation,
                code_references=[CodeReference(path=generated.file_path)],
            )
        )

    return MiniLab(
        repo_url=manifest.repo_url,
        commit_sha=manifest.commit_sha,
        summary=completion.value.summary,
        entries=entries,
        generated_by="super",
    )


def _deterministic(manifest: RepoManifest, known: set[str]) -> MiniLab:
    """A Mini Lab built from the manifest alone, for when no model is available.

    Entries come from the concepts detection already found, each of which
    already carries the code references that justified it -- so the grounding
    requirement is satisfied by construction rather than by filtering.
    """
    entries = [
        MiniLabEntry(
            command=f"explain {concept.name}",
            concept=concept.name,
            explanation=concept.summary,
            code_references=list(concept.code_references[:3]),
        )
        for concept in manifest.concepts
        if concept.code_references
    ]

    for entrypoint in manifest.entrypoints[:4]:
        if not entrypoint.path or entrypoint.path not in known:
            continue
        entries.append(
            MiniLabEntry(
                command=entrypoint.command,
                concept=f"{entrypoint.name} entry point",
                explanation=(
                    f"This is how the software is started. In a real environment it would "
                    f"run {entrypoint.name}, defined in {entrypoint.path}."
                ),
                code_references=[CodeReference(path=entrypoint.path)],
            )
        )

    # Interaction surfaces are the other place grounded evidence reliably lives,
    # and they matter most for exactly the repositories that need a Mini Lab:
    # Cassandra's build is Ant with few recognisable packages, so it yields few
    # concepts -- but its CLI surface cites `bin/cqlsh`, which is precisely what
    # a learner would want explained.
    for surface in manifest.interaction_surfaces:
        if not surface.evidence:
            continue
        entries.append(
            MiniLabEntry(
                command=f"explore the {surface.type.value} surface",
                concept=f"{surface.type.value} interaction",
                explanation=(
                    f"This repository exposes a {surface.type.value} surface. "
                    f"{surface.reason} In a real environment you would interact with it "
                    f"through the files cited below."
                ),
                code_references=list(surface.evidence[:3]),
            )
        )

    return MiniLab(
        repo_url=manifest.repo_url,
        commit_sha=manifest.commit_sha,
        summary=(
            "A conceptual simulation built from this repository's detected concepts. "
            "Nothing here was executed."
        ),
        entries=entries[:MAX_ENTRIES],
        generated_by="deterministic",
    )


def _known_files(manifest: RepoManifest) -> set[str]:
    """Every file path the manifest can vouch for."""
    paths: set[str] = set()
    for concept in manifest.concepts:
        paths.update(reference.path for reference in concept.code_references)
    for surface in manifest.interaction_surfaces:
        paths.update(reference.path for reference in surface.evidence)
    paths.update(entry.path for entry in manifest.entrypoints if entry.path)
    return paths


def _normalise(command: str) -> str:
    return " ".join(command.strip().lower().rstrip(";").split())
